def select_next_node(current_node: int, depot: int, unvisited_nodes: np.ndarray,
                     rest_capacity: float, demands: np.ndarray,
                     distance_matrix: np.ndarray) -> int:
    if unvisited_nodes.size == 0:
        return depot

    d = distance_matrix

    if current_node == depot:
        return int(unvisited_nodes[np.argmax(d[depot][unvisited_nodes])])

    cur_dist = d[current_node][unvisited_nodes]
    savings = d[current_node][depot] + d[unvisited_nodes][depot] - d[current_node][unvisited_nodes]

    # Prefer short continuation while rewarding depot savings;
    # tiny demand term breaks ties in favor of filling the vehicle.
    score = cur_dist - 0.35 * savings + 1e-6 * demands[unvisited_nodes]
    return int(unvisited_nodes[np.argmin(score)])
